/**
 * Minimal bidirectional dictionary implemented in pure JavaScript,
 * mirroring the observable behavior of the Python `bidict` interface
 * used by the original script (membership checks on keys and values).
 *
 * Implemented with plain objects (no Map) to stay within constraints.
 */

class InverseView {
  constructor(owner) {
    this._owner = owner;
  }

  contains(value) {
    return Object.prototype.hasOwnProperty.call(this._owner._inv, value);
  }
}

export class Bidict {
  constructor(entries) {
    this._fwd = Object.create(null);
    this._inv = Object.create(null);
    if (entries) {
      for (const [key, value] of Object.entries(entries)) {
        this.put(key, value);
      }
    }
    this.inv = new InverseView(this);
  }

  put(key, value) {
    const k = String(key);
    const v = String(value);
    if (Object.prototype.hasOwnProperty.call(this._fwd, k)) {
      delete this._inv[this._fwd[k]];
    }
    if (Object.prototype.hasOwnProperty.call(this._inv, v)) {
      delete this._fwd[this._inv[v]];
    }
    this._fwd[k] = v;
    this._inv[v] = k;
  }

  contains(key) {
    return Object.prototype.hasOwnProperty.call(this._fwd, String(key));
  }
}

