/**
 * Minimal command-line argument parser mirroring the observable behavior
 * of Python's argparse for this script: two required options, `--key`
 * (string) and `--val` (integer), both given as `--name value`.
 */

function fail(prog, message) {
  const usage = `usage: ${prog} [-h] --key KEY --val VAL`;
  process.stderr.write(`${usage}\n${prog}: error: ${message}\n`);
  process.exit(2);
}

function parseIntStrict(raw, prog, flag) {
  // argparse's type=int: accepts optional sign followed by digits only.
  if (!/^[+-]?\d+$/.test(raw)) {
    fail(prog, `argument ${flag}: invalid int value: '${raw}'`);
  }
  return parseInt(raw, 10);
}

export function parseArgs(argv, prog) {
  const result = { key: undefined, val: undefined };
  const args = argv.slice(2);

  for (let i = 0; i < args.length; i += 1) {
    const token = args[i];
    let name = token;
    let inlineValue;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      name = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    if (name === '--key' || name === '--val') {
      let raw;
      if (inlineValue !== undefined) {
        raw = inlineValue;
      } else if (i + 1 < args.length) {
        i += 1;
        raw = args[i];
      } else {
        fail(prog, `argument ${name}: expected one argument`);
      }
      if (name === '--key') {
        result.key = raw;
      } else {
        result.val = parseIntStrict(raw, prog, '--val');
      }
    } else if (name === '-h' || name === '--help') {
      process.stdout.write(`usage: ${prog} [-h] --key KEY --val VAL\n`);
      process.exit(0);
    } else {
      fail(prog, `unrecognized arguments: ${token}`);
    }
  }

  const missing = [];
  if (result.key === undefined) missing.push('--key');
  if (result.val === undefined) missing.push('--val');
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  return result;
}

