import { parseArgs } from './lib/argparse.mjs';
import { Bidict } from './lib/bidict.mjs';
import { pyBool, pyPrint } from './lib/pyformat.mjs';

const prog = process.argv[1] ? process.argv[1].split('/').pop() : 'test6.mjs';
const args = parseArgs(process.argv, prog);

// 检查键和值的存在性
const b = new Bidict({ a: 1, b: 2, c: 3 });
const result1 = b.contains(args.key);
const result2 = b.inv.contains(args.val);
pyPrint(pyBool(result1));
pyPrint(pyBool(result2));

